    box.innerHTML = tws.map(t => {
      const who = `@${esc(t.user)}`;
      const nm = t.name ? ` · ${esc(t.name)}` : '';
      const meta = [];
      if (t.likes != null) meta.push(`♥ ${t.likes}`);
      if (t.retweets != null) meta.push(`⇄ ${t.retweets}`);
      if (t.replies != null) meta.push(`↩ ${t.replies}`);
      if (t.createdAt) meta.push(esc(t.createdAt.slice(0, 16).replace('T', ' ')));
