/* ---- fluid wheel navigation ---- */
const el = document.getElementById('globeViz');
let acc = 0, lock = false;
el.addEventListener('wheel', e => {
  e.preventDefault();
  if (lock) return;
  acc += e.deltaY;
  if (Math.abs(acc) >= 55) {
    flyTo(idx + (acc > 0 ? 1 : -1));
    acc = 0;
    lock = true;
    setTimeout(() => { lock = false; acc = 0; }, 650);
  }
}, { passive: false });

